pub(crate) fn built_in_persona_avatar_url(id: &str) -> Option<&'static str> {
    BUILT_IN_PERSONAS
        .iter()
        .find(|persona| persona.id == id)
        .and_then(|persona| persona.avatar_url)
}

/// A starter-team default exactly as a previous release shipped it. The
/// Colony rebrand (Fizz/Honey/Bumble bees to Scout/Forager/Tender entities)
/// upgrades a stored field only when it still equals the shipped value,
/// mirroring the prompt upgrade below: anything else is user-authored and
/// stays untouched.
struct LegacyStarterDefault {
    id: &'static str,
    display_name: &'static str,
    system_prompt: Option<&'static str>,
    avatar_url: &'static str,
    name_pool: &'static [&'static str],
}

