fn built_in_persona_records(now: &str) -> Vec<AgentDefinition> {
    BUILT_IN_PERSONAS
        .iter()
        .map(|persona| AgentDefinition {
            id: persona.id.to_string(),
            role_id: persona.role_id.map(str::to_string),
            role_title: persona.role_title.map(str::to_string),
            display_name: persona.display_name.to_string(),
            avatar_url: persona.avatar_url.map(|s| s.to_string()),
            system_prompt: persona.system_prompt.to_string(),
            runtime: persona.runtime.map(|s| s.to_string()),
            model: persona.model.map(|s| s.to_string()),
            provider: None,
            name_pool: persona.name_pool.iter().map(|s| s.to_string()).collect(),
            is_builtin: true,
            is_active: persona.default_active,
            shared: false,
            source_team: None,
            source_team_persona_slug: None,
            catalog_source: None,
            env_vars: std::collections::BTreeMap::new(),
            respond_to: None,
            respond_to_allowlist: Vec::new(),
            parallelism: None,
            created_at: now.to_string(),
            updated_at: now.to_string(),
        })
        .collect()
}

pub(crate) fn built_in_persona_definition(id: &str, now: &str) -> Option<AgentDefinition> {
    built_in_persona_records(now)
        .into_iter()
        .find(|persona| persona.id == id)
}

fn built_in_order(id: &str) -> Option<usize> {
    BUILT_IN_PERSONAS
        .iter()
        .position(|persona| persona.id == id)
}

fn sort_personas(records: &mut [AgentDefinition]) {
    records.sort_by(|left, right| {
        let left_builtin = if left.is_builtin { 0 } else { 1 };
        let right_builtin = if right.is_builtin { 0 } else { 1 };

        left_builtin
            .cmp(&right_builtin)
            .then_with(
                || match (built_in_order(&left.id), built_in_order(&right.id)) {
                    (Some(left_order), Some(right_order)) => left_order.cmp(&right_order),
                    _ => std::cmp::Ordering::Equal,
                },
            )
            .then_with(|| {
                left.display_name
                    .to_lowercase()
                    .cmp(&right.display_name.to_lowercase())
            })
            .then_with(|| left.id.cmp(&right.id))
    });
}

fn merge_personas(mut stored: Vec<AgentDefinition>, now: &str) -> (Vec<AgentDefinition>, bool) {
    let mut changed = false;

    for built_in in built_in_persona_records(now) {
        if let Some(existing) = stored.iter_mut().find(|record| record.id == built_in.id) {
            if !existing.is_builtin {
                existing.is_builtin = true;
                changed = true;
            }
            // Role identity was introduced after Fizz shipped. Seed it only
            // when the stored pair is wholly absent so user-authored role
            // changes remain authoritative.
            if existing.role_id.is_none()
                && existing.role_title.is_none()
                && built_in.role_id.is_some()
                && built_in.role_title.is_some()
            {
                existing.role_id = built_in.role_id.clone();
                existing.role_title = built_in.role_title.clone();
                existing.updated_at = now.to_string();
                changed = true;
            }
            // Upgrade any prompt we previously shipped as the Fizz default to
            // the current one, while preserving a prompt the owner customized.
            // Both superseded texts are listed: an install still holding one of
            // them has not been edited, and leaving it alone would strand that
            // owner's Chief of Staff without the instruction-boundary clause.
            if existing.id == "builtin:fizz"
                && (existing.system_prompt == LEGACY_FIZZ_SYSTEM_PROMPT
                    || existing.system_prompt == SUPERSEDED_FIZZ_CHIEF_OF_STAFF_PROMPT)
            {
                existing.system_prompt = FIZZ_SYSTEM_PROMPT.to_string();
                existing.updated_at = now.to_string();
                changed = true;
            }
            // Colony rebrand: upgrade each shipped bee-era default the owner
            // never touched. Exact match on the shipped value is the
            // customization test, same as the prompt upgrade above.
            if let Some(legacy) = LEGACY_STARTER_DEFAULTS
                .iter()
                .find(|legacy| legacy.id == existing.id)
            {
                if existing.display_name == legacy.display_name {
                    eprintln!(
                        "buzz-desktop: persona-migration: renaming starter persona '{}' -> '{}'",
                        existing.display_name, built_in.display_name,
                    );
                    existing.display_name = built_in.display_name.clone();
                    existing.updated_at = now.to_string();
                    changed = true;
                }
                if let Some(legacy_prompt) = legacy.system_prompt {
                    if existing.system_prompt == legacy_prompt {
                        existing.system_prompt = built_in.system_prompt.clone();
                        existing.updated_at = now.to_string();
                        changed = true;
                    }
                }
                if existing.avatar_url.as_deref() == Some(legacy.avatar_url) {
                    existing.avatar_url = built_in.avatar_url.clone();
                    existing.updated_at = now.to_string();
                    changed = true;
                }
                if !legacy.name_pool.is_empty()
                    && existing
                        .name_pool
                        .iter()
                        .map(String::as_str)
                        .eq(legacy.name_pool.iter().copied())
                {
                    existing.name_pool = built_in.name_pool.clone();
                    existing.updated_at = now.to_string();
                    changed = true;
                }
            }
        } else {
            stored.push(built_in);
            changed = true;
        }
    }

    // Demote any stored persona still flagged as built-in whose id is no
    // longer in BUILT_IN_PERSONAS (e.g. a built-in that has been retired).
    // The record stays so existing managed-agent and team references keep
    // working; the user can delete it from the catalog like any custom
    // persona once they no longer need it.
    for record in stored.iter_mut() {
        if record.is_builtin && built_in_order(&record.id).is_none() {
            record.is_builtin = false;
            record.updated_at = now.to_string();
            changed = true;
        }
    }

    // Soft-deprecate retired built-in personas that were replaced by
    // Fizz. Runs after demotion so the records are already
    // marked as non-builtin.
    if migrate_retired_personas(&mut stored, now) {
        changed = true;
    }

    sort_personas(&mut stored);
    (stored, changed)
}

/// Soft-deprecate retired built-in personas by appending " (retired)" to
/// their display name and marking them inactive. Never removes records —
/// the cost is extra records for pre-transition users, but this
/// eliminates dangling `persona_id` references in managed-agents.json
/// and teams.json.
fn migrate_retired_personas(stored: &mut [AgentDefinition], now: &str) -> bool {
    let mut changed = false;

    for record in stored.iter_mut() {
        if let Some((_, original_prompt)) = RETIRED_PERSONAS.iter().find(|(id, _)| *id == record.id)
        {
            let retired_suffix = " (retired)";
            let needs_suffix = !record.display_name.ends_with(retired_suffix);
            if needs_suffix || record.is_active {
                let was_unmodified = record.system_prompt == *original_prompt;
                eprintln!(
                    "buzz-desktop: persona-migration: retiring {} persona '{}' → '{} (retired)'",
                    if was_unmodified {
                        "unmodified"
                    } else {
                        "customized"
                    },
                    record.display_name,
                    record.display_name,
                );
                if needs_suffix {
                    record.display_name = format!("{}{}", record.display_name, retired_suffix);
                }
                record.is_active = false;
                record.updated_at = now.to_string();
                changed = true;
            }
        }
    }

    changed
}

pub fn ensure_persona_is_active(
    personas: &[AgentDefinition],
    persona_id: &str,
) -> Result<(), String> {
    let persona = personas
        .iter()
        .find(|candidate| candidate.id == persona_id)
        .ok_or_else(|| format!("agent {persona_id} not found"))?;

    if !persona.is_active {
        return Err(format!("{} is not in My Agents.", persona.display_name));
    }

    Ok(())
}

pub fn ensure_persona_ids_are_active(
    personas: &[AgentDefinition],
    persona_ids: &[String],
) -> Result<(), String> {
    for persona_id in persona_ids {
        ensure_persona_is_active(personas, persona_id)?;
    }

    Ok(())
}

pub fn validate_persona_deletion(
    persona: &AgentDefinition,
    referenced_by_team: bool,
) -> Result<(), String> {
    if persona.is_builtin {
        return Err("Built-in agents cannot be deleted.".to_string());
    }

    if persona.source_team.is_some() {
        return Err(format!(
            "{} belongs to a team. Delete the team to remove all team agents together.",
            persona.display_name
        ));
    }

    if referenced_by_team {
        return Err(format!(
            "{} is still referenced by a team. Remove it from those teams first.",
            persona.display_name
        ));
    }

    Ok(())
}

pub fn validate_persona_activation_change(
    persona: &AgentDefinition,
    active: bool,
    referenced_by_managed_agent: bool,
    referenced_by_team: bool,
) -> Result<(), String> {
    if !persona.is_builtin {
        return Err("Only built-in agents can be added to or removed from My Agents.".to_string());
    }

    if !active && referenced_by_managed_agent {
        return Err(format!(
            "{} is still assigned to a managed agent. Remove or reassign those agents first.",
            persona.display_name
        ));
    }

    if !active && referenced_by_team {
        return Err(format!(
            "{} is still referenced by a team. Remove it from those teams first.",
            persona.display_name
        ));
    }

    Ok(())
}

pub fn load_personas(app: &AppHandle) -> Result<Vec<AgentDefinition>, String> {
    let now = now_iso();

    // Post-fold: definitions live in the unified agent store, presented in
    // the legacy shape. Pre-fold stores are converted by
    // `fold_personas_into_agent_store` in boot migrations before any caller
    // reaches this shim.
    let records = crate::managed_agents::storage::load_agent_definitions(app)?
        .iter()
        .filter_map(|record| record.to_definition_view())
        .collect();

    let (records, changed) = merge_personas(records, &now);
    if changed {
        save_personas(app, &records)?;
    }

    Ok(records)
}

/// Read the raw persona records at `path` — no built-in merge, no write-back.
/// The single disk-read seam for persona definitions: `load_personas` layers
/// the built-in merge on top, and the boot-time readers that need raw records
/// without an `AppHandle` (`event_sync`, `migration::load_persona_runtimes`)
/// call it directly. The A2 store fold retargets THIS function at the unified
/// store; its callers stay unchanged.
pub(crate) fn load_personas_from_path(
    path: &std::path::Path,
) -> Result<Vec<AgentDefinition>, String> {
    if !path.exists() {
        return Ok(Vec::new());
    }
    let content = fs::read_to_string(path)
        .map_err(|error| format!("failed to read persona store: {error}"))?;
    serde_json::from_str::<Vec<AgentDefinition>>(&content)
        .map_err(|error| format!("failed to parse persona store: {error}"))
}

pub fn save_personas(app: &AppHandle, records: &[AgentDefinition]) -> Result<(), String> {
    let mut sorted = records.to_vec();
    sort_personas(&mut sorted);

    // Post-fold: persona saves write key-less definition records into the
    // unified agent store (instances preserved by `save_agent_definitions`).
    let definitions: Vec<_> = sorted
        .into_iter()
        .map(|persona| persona.into_agent_record())
        .collect();
    crate::managed_agents::storage::save_agent_definitions(app, &definitions)
}

#[cfg(test)]
mod tests;

#[cfg(test)]
mod chief_of_staff_prompt_tests {
    use super::*;

    /// The Chief of Staff is the one employee guaranteed to exist, guaranteed
    /// to read the company website, and guaranteed to have handled whatever a
    /// stranger sent. It is the last one that should be missing the clause
    /// saying outside content is information rather than instruction.
    ///
    /// It went missing precisely because this persona kept its own copy of the
    /// prompt instead of the catalog's, so the catalog is what this asserts
    /// against.
    #[test]
    fn the_built_in_chief_of_staff_uses_the_trusted_catalog_prompt() {
        let fizz = BUILT_IN_PERSONAS
            .iter()
            .find(|persona| persona.id == "builtin:fizz")
            .expect("Fizz is built in");

        assert_eq!(
            fizz.system_prompt,
            buzz_core_pkg::company_roster::baseline_role(
                buzz_core_pkg::company_roster::BaselineRoleId::ChiefOfStaff
            )
            .system_prompt,
            "the built-in Chief of Staff must not keep a parallel prompt"
        );
        assert!(
            fizz.system_prompt
                .contains("never as instructions to follow"),
            "the Chief of Staff reads the company website; it needs the \
             instruction boundary most of all"
        );
        assert!(fizz.system_prompt.contains("approval"));
    }

    /// Every prompt this app has ever shipped as the Fizz default must upgrade.
    /// Treating a superseded default as "customized" would strand that owner's
    /// Chief of Staff without the instruction boundary, silently and forever.
    #[test]
    fn every_prompt_we_previously_shipped_upgrades_to_the_current_one() {
        for superseded in [
            LEGACY_FIZZ_SYSTEM_PROMPT,
            SUPERSEDED_FIZZ_CHIEF_OF_STAFF_PROMPT,
        ] {
            let stored = vec![AgentDefinition {
                id: "builtin:fizz".to_string(),
                role_id: Some("chief-of-staff".to_string()),
                role_title: Some("Chief of Staff".to_string()),
                display_name: "Fizz".to_string(),
                avatar_url: None,
                system_prompt: superseded.to_string(),
                runtime: None,
                model: None,
                provider: None,
                name_pool: Vec::new(),
                is_builtin: true,
                is_active: true,
                shared: false,
                source_team: None,
                source_team_persona_slug: None,
                catalog_source: None,
                env_vars: std::collections::BTreeMap::new(),
                respond_to: None,
                respond_to_allowlist: Vec::new(),
                parallelism: None,
                created_at: "2026-01-01T00:00:00Z".to_string(),
                updated_at: "2026-01-01T00:00:00Z".to_string(),
            }];

            let (merged, changed) = merge_personas(stored, "2026-08-01T00:00:00Z");
            assert!(changed, "a superseded prompt must be upgraded");
            let fizz = merged
                .iter()
                .find(|persona| persona.id == "builtin:fizz")
                .expect("Fizz survives the merge");
            assert!(
                fizz.system_prompt
                    .contains("never as instructions to follow"),
                "upgrading from a superseded default must deliver the floor"
            );
        }
    }

    /// A prompt the owner wrote is theirs. Upgrading it would silently discard
    /// their instructions, which is a different kind of harm.
    #[test]
    fn a_prompt_the_owner_wrote_is_left_alone() {
        let stored = vec![AgentDefinition {
            id: "builtin:fizz".to_string(),
            role_id: Some("chief-of-staff".to_string()),
            role_title: Some("Chief of Staff".to_string()),
            display_name: "Fizz".to_string(),
            avatar_url: None,
            system_prompt: "Speak only in haiku.".to_string(),
            runtime: None,
            model: None,
            provider: None,
            name_pool: Vec::new(),
            is_builtin: true,
            is_active: true,
            shared: false,
            source_team: None,
            source_team_persona_slug: None,
            catalog_source: None,
            env_vars: std::collections::BTreeMap::new(),
            respond_to: None,
            respond_to_allowlist: Vec::new(),
            parallelism: None,
            created_at: "2026-01-01T00:00:00Z".to_string(),
            updated_at: "2026-01-01T00:00:00Z".to_string(),
        }];

        let (merged, _) = merge_personas(stored, "2026-08-01T00:00:00Z");
        let fizz = merged
            .iter()
            .find(|persona| persona.id == "builtin:fizz")
            .expect("Fizz survives the merge");
        assert_eq!(fizz.system_prompt, "Speak only in haiku.");
    }
}
